        StringTokenizer st;

        InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    // 求一组测试数据的答案，无解返回 null
    static long[] solveCase(int n, List<Edge>[] g) {
        long[] dist = new long[n + 1];
        boolean[] visited = new boolean[n + 1];
        long[] ans = new long[n + 1];

        ArrayDeque<Integer> queue = new ArrayDeque<>();

        for (int start = 1; start <= n; start++) {
            if (visited[start]) {
                continue;
            }

            // BFS 遍历一个连通块
            List<Integer> comp = new ArrayList<>();
            queue.clear();
            queue.offer(start);
            visited[start] = true;
            dist[start] = 0;

            long mn = 0;
            long mx = 0;

            while (!queue.isEmpty()) {
                int u = queue.poll();
                comp.add(u);

                if (dist[u] < mn) {
                    mn = dist[u];
                }
                if (dist[u] > mx) {
                    mx = dist[u];
                }

                for (Edge e : g[u]) {
                    int v = e.to;
                    long nd = dist[u] + e.w;

                    if (!visited[v]) {
                        visited[v] = true;
                        dist[v] = nd;
                        queue.offer(v);
                    } else {
                        // 已访问过则必须满足相对值一致，否则矛盾
                        if (dist[v] != nd) {
                            return null;
                        }
                    }
                }
            }

            // 令该连通块最小值变成 1
            long add = 1 - mn;

            // 检查平移后最大值是否超过 10^18
            if (mx + add > LIMIT) {
                return null;
            }

            // 计算该连通块的最终答案
            for (int u : comp) {
                ans[u] = dist[u] + add;
            }
        }

        return ans;
    }

    public static void main(String[] args) throws Exception {
        InputReader in = new InputReader();
        StringBuilder sb = new StringBuilder();

        int T = in.nextInt();
        while (T-- > 0) {
            int n = in.nextInt();
            int m = in.nextInt();

            List<Edge>[] g = new ArrayList[n + 1];
            for (int i = 1; i <= n; i++) {
                g[i] = new ArrayList<>();
            }

            for (int t = 0; t < m; t++) {
                int i = in.nextInt();
                int j = in.nextInt();
                long k = in.nextLong();

                g[j].add(new Edge(i, k));
                g[i].add(new Edge(j, -k));
            }

            long[] res = solveCase(n, g);
            if (res == null) {
                sb.append("-1\n");
            } else {
                for (int i = 1; i <= n; i++) {
                    if (i > 1) {
                        sb.append(' ');
                    }
                    sb.append(res[i]);
                }
                sb.append('\n');
            }
        }

        System.out.print(sb.toString());
    }
}
