import sys
from collections import deque

LIMIT = 10 ** 18

def solve_case(n, m, edges):
    # g[u] 中存储 (v, w)，表示 x[v] = x[u] + w
    g = [[] for _ in range(n + 1)]
    for i, j, k in edges:
        g[j].append((i, k))
        g[i].append((j, -k))

    dist = [0] * (n + 1)      # 相对读数
    visited = [False] * (n + 1)
    ans = [0] * (n + 1)

    for start in range(1, n + 1):
        if visited[start]:
            continue

        # BFS 遍历当前连通块
        q = deque([start])
        visited[start] = True
        dist[start] = 0

        comp = []
        mn = 0
        mx = 0

        while q:
            u = q.popleft()
            comp.append(u)

            if dist[u] < mn:
                mn = dist[u]
            if dist[u] > mx:
                mx = dist[u]

            for v, w in g[u]:
                nd = dist[u] + w
                if not visited[v]:
                    visited[v] = True
                    dist[v] = nd
                    q.append(v)
                else:
                    # 已访问的点必须满足相对值一致
                    if dist[v] != nd:
                        return None

        # 平移使最小读数变为 1
        add = 1 - mn
        if mx + add > LIMIT:
            return None

        for u in comp:
            ans[u] = dist[u] + add

    return ans[1:]

def main():
    input = sys.stdin.readline
    T = int(input())
    out = []

    for _ in range(T):
        n, m = map(int, input().split())
        edges = []
        for _ in range(m):
            i, j, k = map(int, input().split())
            edges.append((i, j, k))

        res = solve_case(n, m, edges)
        if res is None:
            out.append("-1")
        else:
            out.append(" ".join(map(str, res)))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
