        boolean[] visited = new boolean[n + 1];
        long[] ans = new long[n + 1];

        ArrayDeque<Integer> queue = new ArrayDeque<>();

        for (int start = 1; start <= n; start++) {
            if (visited[start]) {
                continue;
            }

            List<Integer> comp = new ArrayList<>();
            queue.clear();
            queue.offer(start);
            visited[start] = true;
            dist[start] = 0;

            long mn = 0;
            long mx = 0;

            while (!queue.isEmpty()) {
                int u = queue.poll();
                comp.add(u);

                if (dist[u] < mn) {
                    mn = dist[u];
                }
                if (dist[u] > mx) {
                    mx = dist[u];
                }

                for (Edge e : g[u]) {
                    int v = e.to;
                    long nd = dist[u] + e.w;

                    if (!visited[v]) {
                        visited[v] = true;
                        dist[v] = nd;
                        queue.offer(v);
                    } else {
                        // 已访问的点必须满足相对值一致
                        if (dist[v] != nd) {
                            return null;
                        }
                    }
                }
            }

            // 平移使最小读数变为 1
            long add = 1 - mn;
            if (mx + add > LIMIT) {
                return null;
            }

            for (int u : comp) {
                ans[u] = dist[u] + add;
            }
        }

        return ans;
    }

    public static void main(String[] args) throws Exception {
