            for (int i = 1; i <= n; i++) {
                g[i] = new ArrayList<>();
            }

            for (int t = 0; t < m; t++) {
                int i = in.nextInt();
                int j = in.nextInt();
                long k = in.nextLong();

                g[j].add(new Edge(i, k));
                g[i].add(new Edge(j, -k));
            }

            long[] res = solveCase(n, g);
            if (res == null) {
                sb.append("-1\n");
            } else {
                for (int i = 1; i <= n; i++) {
                    if (i > 1) {
                        sb.append(' ');
                    }
                    sb.append(res[i]);
                }
                sb.append('\n');
            }
        }

        System.out.print(sb.toString());
    }
